import Foundation

public enum Setting: String, Codable, Sendable, CaseIterable { case cafe, shop, event, other }
public enum Goal: String, Codable, Sendable, CaseIterable { case enter, deepen, explain }
public enum Strategy: String, Codable, Sendable, CaseIterable { case followUp, personalConnection, explainClearly, reflectClarify, situationalOpener }
public enum SessionMode: String, Codable, Sendable, CaseIterable { case live, practice }
public enum ModelID: String, Codable, Sendable, CaseIterable { case gemma4E4B, gemma4E2B }
public enum DeliveryStatus: String, Codable, Sendable, CaseIterable { case pending, completed, failed, cancelled }
public enum FeedbackVerdict: String, Codable, Sendable, CaseIterable { case helpful, unhelpful, notTried, invalidEvidence }
public enum ModelJob: String, Codable, Sendable, CaseIterable { case scene, cue, audit, practice }
public enum Coverage: String, Codable, Sendable, CaseIterable { case complete, partial, unavailable }
public enum AuditStatus: String, Codable, Sendable, CaseIterable { case ready, waitingForTranscript }

public struct ModelProfile: Codable, Sendable, Equatable, Hashable { public var modelID: ModelID; public var artifactSHA256: String; public var promptVersion: String; public init(modelID: ModelID, artifactSHA256: String, promptVersion: String) { self.modelID = modelID; self.artifactSHA256 = artifactSHA256; self.promptVersion = promptVersion } }
public struct Evidence: Codable, Sendable, Equatable, Identifiable { public var sourceID: String; public var text: String; public var speaker: String?; public var utteredAt: Date?; public var shareApproved: Bool; public var id: String { sourceID }; public init(sourceID: String, text: String, speaker: String? = nil, utteredAt: Date? = nil, shareApproved: Bool = false) { self.sourceID = sourceID; self.text = text; self.speaker = speaker; self.utteredAt = utteredAt; self.shareApproved = shareApproved } }
public struct MemorySnapshot: Codable, Sendable, Equatable { public var approvedMemories: [Evidence]; public var dialogue: [Evidence]; public var fetchedAt: Date; public var coverage: Coverage; public init(approvedMemories: [Evidence], dialogue: [Evidence], fetchedAt: Date, coverage: Coverage) { self.approvedMemories = approvedMemories; self.dialogue = dialogue; self.fetchedAt = fetchedAt; self.coverage = coverage } }
public struct SceneFacts: Codable, Sendable, Equatable { public var requestID: UUID; public var observedAt: Date; public var setting: Setting; public var observations: [String]; public var uncertain: Bool; public init(requestID: UUID, observedAt: Date, setting: Setting, observations: [String], uncertain: Bool) { self.requestID = requestID; self.observedAt = observedAt; self.setting = setting; self.observations = observations; self.uncertain = uncertain } }
public struct CueContext: Codable, Sendable, Equatable { public var decisionID: UUID; public var requestedAt: Date; public var scene: SceneFacts; public var goal: Goal; public var mode: SessionMode; public var profile: ModelProfile; public var snapshot: MemorySnapshot; public var knownPoint: String?; public var disabledStrategies: [Strategy]; /// Decision-scoped citation for wearer-entered knownPoint text.
    public var knownPointSourceID: String?; public init(decisionID: UUID, requestedAt: Date, scene: SceneFacts, goal: Goal, mode: SessionMode, profile: ModelProfile, snapshot: MemorySnapshot, knownPoint: String? = nil, disabledStrategies: [Strategy] = [], knownPointSourceID: String? = nil) { self.decisionID = decisionID; self.requestedAt = requestedAt; self.scene = scene; self.goal = goal; self.mode = mode; self.profile = profile; self.snapshot = snapshot; self.knownPoint = knownPoint; self.disabledStrategies = disabledStrategies; self.knownPointSourceID = knownPointSourceID } }
public struct CueDecision: Codable, Sendable, Equatable { public var context: CueContext; public var features: [Double]; public var eligibleActions: [Strategy]; public var selectedAction: Strategy; public var utilities: [String: Double]; public var policyVersion: String; public var usedExploration: Bool; public init(context: CueContext, features: [Double], eligibleActions: [Strategy], selectedAction: Strategy, utilities: [String: Double], policyVersion: String, usedExploration: Bool) { self.context = context; self.features = features; self.eligibleActions = eligibleActions; self.selectedAction = selectedAction; self.utilities = utilities; self.policyVersion = policyVersion; self.usedExploration = usedExploration } }
public struct CueResult: Codable, Sendable, Equatable { public var decisionID: UUID; public var actualProfile: ModelProfile; public var strategy: Strategy; public var text: String; public var sourceIDs: [String]; public init(decisionID: UUID, actualProfile: ModelProfile, strategy: Strategy, text: String, sourceIDs: [String]) { self.decisionID = decisionID; self.actualProfile = actualProfile; self.strategy = strategy; self.text = text; self.sourceIDs = sourceIDs } }
public struct FeedbackEvent: Codable, Sendable, Equatable, Identifiable { public var id: UUID; public var decisionID: UUID; public var verdict: FeedbackVerdict; public var revision: Int; public var recordedAt: Date; public init(id: UUID = UUID(), decisionID: UUID, verdict: FeedbackVerdict, revision: Int, recordedAt: Date = Date()) { self.id = id; self.decisionID = decisionID; self.verdict = verdict; self.revision = revision; self.recordedAt = recordedAt } }
public struct Episode: Codable, Sendable, Equatable, Identifiable { public var decision: CueDecision; public var cue: CueResult?; public var delivery: DeliveryStatus; public var feedback: FeedbackEvent?; public var id: UUID { decision.context.decisionID }; public init(decision: CueDecision, cue: CueResult? = nil, delivery: DeliveryStatus = .pending, feedback: FeedbackEvent? = nil) { self.decision = decision; self.cue = cue; self.delivery = delivery; self.feedback = feedback } }
public struct AuditReport: Codable, Sendable, Equatable { public var decisionID: UUID; public var generationProfile: ModelProfile?; public var status: AuditStatus; public var strength: String?; public var opportunity: String?; public var exercise: String?; public var sourceIDs: [String]; public var principleID: String?; public init(decisionID: UUID, generationProfile: ModelProfile?, status: AuditStatus, strength: String? = nil, opportunity: String? = nil, exercise: String? = nil, sourceIDs: [String] = [], principleID: String? = nil) { self.decisionID = decisionID; self.generationProfile = generationProfile; self.status = status; self.strength = strength; self.opportunity = opportunity; self.exercise = exercise; self.sourceIDs = sourceIDs; self.principleID = principleID } }
public struct ModelRequest: Codable, Sendable, Equatable { public var requestID: UUID; public var decisionID: UUID?; public var kind: ModelJob; public var requestedProfile: ModelProfile; public var prompt: String; public var imageJPEG: Data?; public var maxOutputTokens: Int; public var responseSchemaJSON: String?; public init(requestID: UUID, decisionID: UUID? = nil, kind: ModelJob, requestedProfile: ModelProfile, prompt: String, imageJPEG: Data? = nil, maxOutputTokens: Int, responseSchemaJSON: String? = nil) { self.requestID = requestID; self.decisionID = decisionID; self.kind = kind; self.requestedProfile = requestedProfile; self.prompt = prompt; self.imageJPEG = imageJPEG; self.maxOutputTokens = maxOutputTokens; self.responseSchemaJSON = responseSchemaJSON } }
public struct ModelResponse: Codable, Sendable, Equatable { public var requestID: UUID; public var actualProfile: ModelProfile; public var text: String; public init(requestID: UUID, actualProfile: ModelProfile, text: String) { self.requestID = requestID; self.actualProfile = actualProfile; self.text = text } }
public enum ModelResponseError: Error, Equatable { case requestMismatch, profileMismatch, emptyOutput }
public extension ModelResponse {
    /// Rejects silent model substitution before any generated field is consumed.
    func validate(for request: ModelRequest) throws {
        guard requestID == request.requestID else { throw ModelResponseError.requestMismatch }
        guard actualProfile == request.requestedProfile else { throw ModelResponseError.profileMismatch }
        guard !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { throw ModelResponseError.emptyOutput }
    }
}

public protocol ModelGenerating: Sendable { func activeProfile() async throws -> ModelProfile; func generate(_ request: ModelRequest) async throws -> ModelResponse }

public enum VoiceEventKind: String, Codable, Sendable, CaseIterable { case started, completed, failed, cancelled }
public struct SpeechRequest: Codable, Sendable, Equatable { public var requestID: UUID; public var sessionID: UUID; public var generation: Int; public var decisionID: UUID?; public var profile: ModelProfile; public var mode: SessionMode; public var text: String; public init(requestID: UUID, sessionID: UUID, generation: Int, decisionID: UUID?, profile: ModelProfile, mode: SessionMode, text: String) { self.requestID = requestID; self.sessionID = sessionID; self.generation = generation; self.decisionID = decisionID; self.profile = profile; self.mode = mode; self.text = text } }
public struct VoiceEvent: Codable, Sendable, Equatable { public var requestID: UUID; public var sessionID: UUID; public var generation: Int; public var kind: VoiceEventKind; public var occurredAt: Date; public var errorMessage: String?; public init(requestID: UUID, sessionID: UUID, generation: Int, kind: VoiceEventKind, occurredAt: Date = Date(), errorMessage: String? = nil) { self.requestID = requestID; self.sessionID = sessionID; self.generation = generation; self.kind = kind; self.occurredAt = occurredAt; self.errorMessage = errorMessage } }
public struct PracticeTurn: Codable, Sendable, Equatable, Identifiable { public var id: UUID; public var sessionID: UUID; public var generation: Int; public var text: String; public var utteredAt: Date; public var isFinal: Bool; public init(id: UUID, sessionID: UUID, generation: Int, text: String, utteredAt: Date = Date(), isFinal: Bool) { self.id = id; self.sessionID = sessionID; self.generation = generation; self.text = text; self.utteredAt = utteredAt; self.isFinal = isFinal } }
public protocol VoiceCoordinating: Sendable { func speak(_ request: SpeechRequest) async throws -> AsyncThrowingStream<VoiceEvent, Error>; func cancel(sessionID: UUID) async; func startPractice(sessionID: UUID, generation: Int) async throws -> AsyncThrowingStream<PracticeTurn, Error>; func stopPractice(sessionID: UUID) async }

public struct CoachingCard: Codable, Sendable, Equatable, Identifiable { public var id: String; public var title: String; public var principle: String; public var exercise: String; public var bookTitle: String; public var sourceURL: String; public init(id: String, title: String, principle: String, exercise: String, bookTitle: String, sourceURL: String) { self.id = id; self.title = title; self.principle = principle; self.exercise = exercise; self.bookTitle = bookTitle; self.sourceURL = sourceURL } }
public struct PracticeScenario: Codable, Sendable, Equatable, Identifiable { public var id: String; public var title: String; public var setting: Setting; public var goal: Goal; public var openingLine: String; public var partnerInstructions: String; public var principleIDs: [String]; public init(id: String, title: String, setting: Setting, goal: Goal, openingLine: String, partnerInstructions: String, principleIDs: [String]) { self.id = id; self.title = title; self.setting = setting; self.goal = goal; self.openingLine = openingLine; self.partnerInstructions = partnerInstructions; self.principleIDs = principleIDs } }
